```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    printf("Program is running...\n");
    // Perform some operations...

    // Terminate the program
    exit(0);  // Exit with status 0 (success)
    // The following line will never be executed
    return 1; // This is just for completeness, but it won't affect the program termination.
}
```

